package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Node_siblingNodes_TriageGen0Test {

    private Node parentNode;
    private Node childNode1;
    private Node childNode2;
    private Node childNode3;

    @Before
    public void setUp() {
        Document doc = new Document("");
        parentNode = new Element("div", doc);
        childNode1 = new TextNode("First", doc);
        childNode2 = new Element("span", doc);
        childNode3 = new TextNode("Third", doc);
        parentNode.appendChild(childNode1);
        parentNode.appendChild(childNode2);
        parentNode.appendChild(childNode3);
    }

    @Test
    public void testSiblingNodes() {
        // When
        List<Node> siblings = childNode2.siblingNodes();

        // Then
        assertEquals(3, siblings.size());
        assertEquals(childNode1, siblings.get(0));
        assertEquals(childNode2, siblings.get(1));
        assertEquals(childNode3, siblings.get(2));
    }

    @Test
    public void testSiblingNodesWithNoSiblings() {
        // When
        List<Node> siblings = childNode1.siblingNodes();

        // Then
        assertEquals(3, siblings.size());
        assertEquals(childNode1, siblings.get(0));
        assertEquals(childNode2, siblings.get(1));
        assertEquals(childNode3, siblings.get(2));
    }

    @Test
    public void testSiblingNodesForRootNode() {
        // When
        Node root = new Element("root", new Document(""));
        List<Node> siblings = root.siblingNodes();

        // Then
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingNodesWithNullParent() {
        // Given
        Node node = new TextNode("No Parent", new Document(""));

        // When
        List<Node> siblings = node.siblingNodes();

        // Then
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingNodesWithSingleNode() {
        // Given
        Node loneNode = new Element("lone", new Document(""));
        loneNode.setParentNode(loneNode);

        // When
        List<Node> siblings = loneNode.siblingNodes();

        // Then
        assertTrue(siblings.isEmpty());
    }
}
